import{_ as e,o as a,c as r,a5 as d}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"氧化物","description":"","frontmatter":{"title":"氧化物","mineralGroup":"oxides"},"headers":[],"relativePath":"zh/classification/mineral-groups/oxides.md","filePath":"zh/classification/mineral-groups/oxides.md","lastUpdated":1790876393000}'),l={name:"zh/classification/mineral-groups/oxides.md"};function i(o,t,s,n,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="氧化物" tabindex="-1">氧化物 <a class="header-anchor" href="#氧化物" aria-label="Permalink to &quot;氧化物&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>氧化物类是宝石学最重要类之一，涵盖刚玉族（红宝石、蓝宝石）、 尖晶石族、金红石族、水铝矿等。致色元素以过渡金属为主 （Cr、Fe、Ti、V）。因晶格中化学键强（离子键 + 部分共价性）， 氧化物硬度普遍较高（Mohs 7–9），是良好的耐久性宝石。</p><h2 id="化学式类型" tabindex="-1">化学式类型 <a class="header-anchor" href="#化学式类型" aria-label="Permalink to &quot;化学式类型&quot;">​</a></h2><p>M₂O₃ / MO₂ / MO</p><h2 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h2><p>氧离子（O²⁻）构成六方最密堆积或立方最密堆积骨架，金属阳离子 填充八面体或四面体间隙位置。刚玉族为三方晶系，尖晶石族为等轴 晶系。</p><h2 id="代表性宝石" tabindex="-1">代表性宝石 <a class="header-anchor" href="#代表性宝石" aria-label="Permalink to &quot;代表性宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>化学式</th><th>亚族</th></tr></thead><tbody><tr><td>Ruby / 红宝石</td><td>Al₂O₃ + Cr</td><td>corundum</td></tr><tr><td>Sapphire (blue) / 蓝宝石</td><td>Al₂O₃ + Fe,Ti</td><td>corundum</td></tr><tr><td>Yellow Sapphire / 黄宝石</td><td>Al₂O₃ + Fe</td><td>corundum</td></tr><tr><td>Padparadscha / 帕帕拉恰</td><td>Al₂O₃ + Cr,Fe</td><td>corundum</td></tr><tr><td>Spinel / 尖晶石</td><td>MgAl₂O₄</td><td>spinel</td></tr><tr><td>Hematite / 赤铁矿</td><td>Fe₂O₃</td><td>hematite</td></tr><tr><td>Rutile / 金红石</td><td>TiO₂</td><td>rutile</td></tr><tr><td>Diaspore / 水铝石</td><td>AlO(OH)</td><td>boehmite</td></tr><tr><td>Chrysoberyl / 金绿宝石</td><td>BeAl₂O₄</td><td>chrysoberyl</td></tr><tr><td>Cassiterite / 锡石</td><td>SnO₂</td><td>rutile</td></tr><tr><td>Spinel (cobalt-blue) / 钴蓝尖晶石</td><td>CoAl₂O₄</td><td>spinel</td></tr></tbody></table><p><em>详见<a href="./intro.html">矿物组总览</a>。</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA：宝石的矿物种、品种与矿物组</a><span>矿物种、宝石品种与矿物组的层级关系</span><small>打开来源 ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat 矿物数据库</a><span>矿物名称、化学组成与分类检索</span><small>打开来源 ↗</small></li></ul></aside>',11)])])}const u=e(l,[["render",i]]);export{m as __pageData,u as default};
